# -*- coding: utf-8 -*-
# Сверка с ответами учебника Макарычев 9, часть 3 (расхождения 130–199): пересчитано вручную + SymPy (check_mk3.py), условия сверены со сканом.
KB = "ключ неверен (сверка с ответом учебника Макарычев 9 и пересчёт вручную): "
SRC = "сверка с ответами учебника Макарычев 9 (углублённый) 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
K("G9_TB_18_343", r"$b \in (-\infty; 2 - \sqrt{10}) \cup (2 + \sqrt{10}; +\infty)$", "при b = 1 есть корень; иначе D/4 = 9 − (b − 1)(b − 3) < 0 ⇔ b² − 4b − 6 > 0 (было (−∞; −1) ∪ (4; +∞))")
K("G9_TB_6_86_3", r"$(\dfrac{4}{9})^{-6}; (\dfrac{4}{9})^{-5}; (\dfrac{4}{9})^{0}; \dfrac{4}{9}$", "(4/9)⁻⁶ = (9/4)⁶ > (9/4)⁵ = (4/9)⁻⁵ (первые два числа стояли в обратном порядке); вариант с тем же порядком закрыт",
  drop=[0], dadd=OLD(r"$(\dfrac{4}{9})^{-5}; (\dfrac{4}{9})^{-6}; (\dfrac{4}{9})^{0}; \dfrac{4}{9}$", "перепутан порядок степеней"))
K("G9_TB_13_204", r"$a = -6$, $b = 26$", "a + b = 20, 4a + 2b = 28 ⇒ a = −6, b = 26 (было −3 и 23: −3 + 23 − 18 = 2, но −12 + 46 − 18 = 16 ≠ 10)")
K("G9_TB_14_233_3", r"$0$", "a³(a − 2)²/((a − 2)(a + 2)(a² + 4)): при a = 2 знаменатель равен 0, остаётся a = 0 (было 0; 2)")
K("G9_TB_14_232", r"$66$ ч и $55$ ч", "1/x + 1/(x − 11) = 1/30 ⇒ x² − 71x + 330 = 0 ⇒ x = 66 (было 55 и 44: 1/55 + 1/44 ≠ 1/30)")
K("G9_TB_18_342", r"$a \in (-4; -2) \cup (-2; 6)$", "a ≠ −2, D/4 = 16 − (a + 2)(a − 4) > 0 ⇔ a² − 2a − 24 < 0 ⇔ −4 < a < 6 (было (−6; 4) ∪ (4; +∞))",
  dadd=OLD(r"$a \in (-6; 4) \cup (4; +\infty)$", "ошибка в дискриминанте"))
K("G9_TB_20_395", r"$(5{,}4; 10{,}8)$", "k = 2; (x − 4)² + (2x − 6)² = 25 ⇒ 5x² − 32x + 27 = 0 ⇒ x = 1 или 5,4 (было (7; 6) — не лежит на прямой y = 2x)")
K("G9_TB_21_403_1", r"$1$", "расстояние от центра (6; −4) до прямой y = −2 равно 2 = r — касание, одна точка (было 2)", dadd=OLD(r"$2$", "не замечено касание"))
P["G9_TB_25_474_2"] = {"q": "Найдите все решения системы уравнений:\nб)\n$$\n\\begin{cases}\n2x^{2} - 6y = xy, \\\\\n3x^{2} - 8y = 0{,}5xy\n\\end{cases}\n$$", "src": SRC,
  "why": "в условии была искажена запись: десятичная дробь 0,5 во втором уравнении разорвана на «0,» и отдельную строку «5xy» (Макарычев 9, № 474 б); ключ (0; 0), (−1; 0,4) верен"}
K("G9_TB_28_572_2", r"$S_{50} = 1075$, $S_{100} = 4650$, $S_{n} = \dfrac{n(n-7)}{2}$", "Sₙ = n(−3 + n − 4)/2 = n(n − 7)/2, S₅₀ = 1075, S₁₀₀ = 4650 (в ключе не было S₅₀ и S₁₀₀, о которых спрашивается)")
K("G9_TB_29_599_2", r"$-162$", "q² = 9, b₇ = b₁q⁶ = −2/9 · 729 = −162 при обоих q (было −162 и 162)")
K("G9_TB_ЗПТ_886", r"$98$ и $2$ или $54$ и $6$", "a = kb: k(b + 1)² = 441 ⇒ b + 1 ∈ {3; 7} (b = 20 даёт равные числа) ⇒ 98 и 2, 54 и 6 (было 20 и 21 — сумма не 441)")
K("G9_TB_ЗПТ_874", r"$1$, $4$, $7$", "(4 + d)² = (1 + 2d)² ⇒ d = 3 (d = −5/3 не целое): 1, 7, 49 — геометрическая (было 1, 3, 5 или 1, −1, −3)", dadd=OLD(r"$1$, $3$, $5$ или $1$, $-1$, $-3$", "не проверено условие"))
K("G9_TB_УПК_794", r"$18$, $12$, $8$", "q = 20/30 = 2/3, b₁ = 18 — решение единственное; 45, −15, 5 не подходит: −15 + 5 ≠ 20", dadd=OLD(r"$18$, $12$, $8$ или $45$, $-15$, $5$", "лишнее решение"))
K("G9_TB_УПК_790", r"$\dfrac{2}{27}$", "b₅ = b₃q² = 2/3 · 1/9 = 2/27 при обоих q = ±1/3 (было ±2/27)")
K("G9_TB_ЗПТ_879", r"$(8; -8; 8)$, $(-8; 8; 8)$", "(x + y)² = 2z² − 2z² = 0 ⇒ x + y = 0 ⇒ z = 8, xy = −64 ⇒ (8; −8; 8), (−8; 8; 8) (ключ был англоязычным текстом решения внутри формулы)")
K("G9_TB_18_303_2", r"$p = -1$; $p = 1 - \sqrt{2}$; $p = 1 + \sqrt{2}$", "p³ − p² − 3p − 1 = (p + 1)(p² − 2p − 1) (были потеряны корни 1 ± √2)")
K("G9_TB_26_520_1", r"Объединение двух замкнутых прямых углов: $x \geq 1$, $y \geq 1$ или $x \leq 1$, $y \leq 1$.", "множество — два вертикальных прямых угла с вершиной (1; 1), а не полуплоскости (формулировка ключа была неверной)")
